"summary": "The container 'api' is consistently throttled at its CPU limit, causing readiness probe failures. Increasing the CPU limit to 750m will alleviate throttling and resolve the timeouts.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "The container is throttled at 0.5 CPU cores (usage 0.495, 64% throttling ratio), leading to sustained performance degradation and readiness probe timeouts.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "The increased CPU limit will reduce throttling, allowing the container to meet its CPU demand and pass readiness probes.",
  "rationale": "The container is consistently throttled at 0.5 CPU cores (usage 0.495, 64% throttling ratio), causing readiness probe timeouts. Raising the limit to 750m (1.5x current) will clear the throttling without affecting memory or other resources.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
